"""Plain text absence notices for parents."""

from rosterkit.models import Student
from rosterkit.errors import ProjectError

def absent_days(student, marks):
    """Sorted absent dates; raises on foreign or no marks."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark for {mark.student_id} given"
                f" with student {student.student_id}"
            )
    days = [m.day for m in marks if m.status == "absent"]
    if not days:
        raise ProjectError("no absences to write about")
    return sorted(days)

def absence_notice(student: Student, marks) -> str:
    """Short notice naming the student and missed dates."""
    days = absent_days(student, marks)
    listed = "\n".join(f"- {day.isoformat()}" for day in days)
    return (
        f"Dear parent or guardian,\n\n"
        f"{student.first_name} {student.last_name} missed"
        f" {len(days)} day(s) of school:\n{listed}\n"
    )
